<?php $initials = static function (string $name): string { $parts = preg_split('/\s+/', trim($name)) ?: []; $value = ''; foreach (array_slice($parts, 0, 2) as $part) { $value .= strtoupper(substr($part, 0, 1)); } return $value ?: 'AT'; }; ?>
<section>
    <div class="section-heading"><div><p class="eyebrow">Cadastros esportivos</p><h1>Atletas</h1><p>Atletas cadastrados sem depender da inscricao no campeonato.</p></div><?php if ($canCreate): ?><a class="button" href="<?= App\Core\View::e(App\Core\Config::url('/admin/atletas/nova')) ?>">Novo atleta</a><?php endif; ?></div>
    <?php if (!empty($message)): ?><p class="success" role="status"><?= App\Core\View::e($message) ?></p><?php endif; ?>
    <form method="get" class="filters"><label>Busca <input name="search" value="<?= App\Core\View::e($query['search'] ?? '') ?>"></label><label>Equipe <select name="team_id"><option value="">Todas</option><?php foreach ($teams as $team): ?><option value="<?= (int) $team['id'] ?>" <?= (string) ($query['team_id'] ?? '') === (string) $team['id'] ? 'selected' : '' ?>><?= App\Core\View::e($team['name']) ?></option><?php endforeach; ?></select></label><label>Posição <select name="primary_position_id"><option value="">Todas</option><?php foreach ($positions as $position): ?><option value="<?= (int) $position['id'] ?>" <?= (string) ($query['primary_position_id'] ?? '') === (string) $position['id'] ? 'selected' : '' ?>><?= App\Core\View::e($position['name']) ?></option><?php endforeach; ?></select></label><label>Idade minima <input type="number" name="age_min" min="0" max="120" value="<?= App\Core\View::e($query['age_min'] ?? '') ?>"></label><label>Idade maxima <input type="number" name="age_max" min="0" max="120" value="<?= App\Core\View::e($query['age_max'] ?? '') ?>"></label><label>Status <select name="status"><option value="">Todos</option><?php foreach (['draft', 'active', 'inactive', 'blocked', 'transferred', 'archived'] as $status): ?><option value="<?= $status ?>" <?= ($query['status'] ?? '') === $status ? 'selected' : '' ?>><?= App\Core\View::e($status) ?></option><?php endforeach; ?></select></label><button type="submit">Filtrar</button></form>
    <?php if ($items === []): ?><p>Nenhum atleta encontrado.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Equipe</th><th>Idade</th><th>Posição</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><span class="athlete-list-avatar" aria-hidden="true"><?= App\Core\View::e($initials((string) ($item['sporting_name'] ?: $item['full_name']))) ?></span><strong><?= App\Core\View::e($item['sporting_name'] ?: $item['full_name']) ?></strong><br><small><?= App\Core\View::e($item['full_name']) ?></small></td><td><?= App\Core\View::e($item['team_name']) ?></td><td><?= (int) $item['age'] ?></td><td><?= App\Core\View::e($item['primary_position_name']) ?></td><td><span class="status status-<?= App\Core\View::e($item['status']) ?>"><?= App\Core\View::e($item['status']) ?></span></td><td><a href="<?= App\Core\View::e(App\Core\Config::url('/admin/atletas/' . $item['id'])) ?>">Abrir</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section>
